INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (1,164,'2025-10-09 11:14:00','[Diseño UX/UI] Después de varias semanas trabajando con investigación de usuarios, estas son mis tres recomendaciones: definir objetivos claros, medir resultados y documentar los aprendizajes.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (2,36,'2025-03-31 17:27:00','[Recursos humanos] Después de varias semanas trabajando con bienestar laboral, estas son mis tres recomendaciones: definir objetivos claros, medir resultados y documentar los aprendizajes.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (3,9,'2025-08-12 11:32:00','[Datos y analítica] Hoy comparto algunas conclusiones de nuestro último proyecto sobre visualización de datos. La colaboración entre perfiles diferentes ha sido fundamental para obtener buenos resultados. ¿Qué experiencias habéis tenido?');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (4,155,'2025-07-23 19:41:00','[Marketing digital] Hoy comparto algunas conclusiones de nuestro último proyecto sobre posicionamiento de marca. La colaboración entre perfiles diferentes ha sido fundamental para obtener buenos resultados. ¿Qué experiencias habéis tenido?');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (5,180,'2026-04-05 17:17:00','[Cloud y DevOps] He publicado una guía introductoria sobre integración continua para equipos que quieren empezar con una metodología práctica y sostenible.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (6,2,'2026-03-09 13:17:00','[Inteligencia artificial] Estamos preparando una sesión práctica sobre IA generativa. Me interesa especialmente conocer casos reales y retos que se encuentran los equipos en su día a día.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (7,40,'2025-04-15 09:24:00','[Cloud y DevOps] Una reflexión sobre infraestructura como código: la tecnología aporta valor cuando resuelve problemas concretos y mejora la experiencia de las personas.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (8,25,'2026-09-11 12:51:00','[Marketing digital] Busco intercambiar experiencias con profesionales que estén trabajando en estrategia de contenidos. Compartir conocimientos ayuda a impulsar mejores proyectos.');
INSERT INTO publicaciones (id,id_persona,fecha,contenidos) VALUES (9,12,'2025-05-08 14:05:00','[Inteligencia artificial] En el encuentro profesional de ayer debatimos sobre visión artificial. Me quedo con una idea: experimentar en pequeño, aprender rápido y escalar con criterio.');
